package br.com.admeclesial.interfaces.rest.financeiro; import br.com.admeclesial.application.financeiro.*; import br.com.admeclesial.domain.financeiro.ContaAPagar; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/contas-a-pagar") public class ContaAPagarRestController { final ContaAPagarApplicationService s; public ContaAPagarRestController(ContaAPagarApplicationService s){this.s=s;} @PostMapping public ContaAPagar criar(@Valid @RequestBody ContaAPagarRequest r){return s.criar(r);} @GetMapping public List<ContaAPagar> listar(){return s.listar();} }